-- ACCT-006: reviewed bank statements, exact source matches and immutable sign-offs.
CREATE TABLE tt_reconcile_statements(id TEXT PRIMARY KEY,bank_id TEXT NOT NULL REFERENCES tt_operating_accounts(id),from_day TEXT NOT NULL,to_day TEXT NOT NULL,opening_cents INTEGER NOT NULL,closing_cents INTEGER NOT NULL,format TEXT NOT NULL,reference TEXT NOT NULL,fingerprint TEXT NOT NULL,original BLOB NOT NULL,lines TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(bank_id,from_day,to_day),UNIQUE(bank_id,fingerprint));
CREATE TABLE tt_reconcile_matches(id TEXT PRIMARY KEY,statement_id TEXT NOT NULL REFERENCES tt_reconcile_statements(id),bank_id TEXT NOT NULL,bank_key TEXT NOT NULL,method TEXT NOT NULL,reference TEXT NOT NULL,recorded_by TEXT NOT NULL,recorded_at TEXT NOT NULL,UNIQUE(bank_id,bank_key));
CREATE TABLE tt_reconcile_sources(match_id TEXT NOT NULL REFERENCES tt_reconcile_matches(id),bank_id TEXT NOT NULL,source_key TEXT NOT NULL,PRIMARY KEY(bank_id,source_key));
CREATE TABLE tt_reconcile_outstanding(statement_id TEXT NOT NULL REFERENCES tt_reconcile_statements(id),source_key TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('check','deposit','other')),reference TEXT NOT NULL,recorded_by TEXT NOT NULL,recorded_at TEXT NOT NULL,PRIMARY KEY(statement_id,source_key));
CREATE TABLE tt_reconcile_signoffs(id TEXT PRIMARY KEY,statement_id TEXT NOT NULL REFERENCES tt_reconcile_statements(id),fingerprint TEXT NOT NULL,snapshot TEXT NOT NULL,signed_by TEXT NOT NULL,signed_at TEXT NOT NULL,UNIQUE(statement_id,fingerprint));
CREATE TABLE tt_reconcile_clock(id INTEGER PRIMARY KEY CHECK(id=1),version INTEGER NOT NULL);
INSERT INTO tt_reconcile_clock VALUES(1,0);
INSERT INTO tt_role_actions(role,action) SELECT role,'reconcile.read' FROM tt_role_actions WHERE action='reports.read';
INSERT INTO tt_role_actions(role,action) SELECT role,'reconcile.import' FROM tt_role_actions WHERE action='journal.post';
INSERT INTO tt_role_actions(role,action) SELECT role,'reconcile.match' FROM tt_role_actions WHERE action='journal.post';
INSERT INTO tt_role_actions(role,action) SELECT role,'reconcile.outstanding' FROM tt_role_actions WHERE action='journal.post';
INSERT INTO tt_role_actions(role,action) SELECT role,'reconcile.signoff' FROM tt_role_actions WHERE action='period.signoff';
CREATE TRIGGER tt_reconcile_statements_update BEFORE UPDATE ON tt_reconcile_statements BEGIN SELECT RAISE(ABORT,'Reconciliation evidence is immutable'); END;
CREATE TRIGGER tt_reconcile_statements_delete BEFORE DELETE ON tt_reconcile_statements BEGIN SELECT RAISE(ABORT,'Reconciliation evidence is immutable'); END;
CREATE TRIGGER tt_reconcile_matches_update BEFORE UPDATE ON tt_reconcile_matches BEGIN SELECT RAISE(ABORT,'Reconciliation evidence is immutable'); END;
CREATE TRIGGER tt_reconcile_matches_delete BEFORE DELETE ON tt_reconcile_matches BEGIN SELECT RAISE(ABORT,'Reconciliation evidence is immutable'); END;
CREATE TRIGGER tt_reconcile_sources_update BEFORE UPDATE ON tt_reconcile_sources BEGIN SELECT RAISE(ABORT,'Reconciliation evidence is immutable'); END;
CREATE TRIGGER tt_reconcile_sources_delete BEFORE DELETE ON tt_reconcile_sources BEGIN SELECT RAISE(ABORT,'Reconciliation evidence is immutable'); END;
CREATE TRIGGER tt_reconcile_outstanding_update BEFORE UPDATE ON tt_reconcile_outstanding BEGIN SELECT RAISE(ABORT,'Reconciliation evidence is immutable'); END;
CREATE TRIGGER tt_reconcile_outstanding_delete BEFORE DELETE ON tt_reconcile_outstanding BEGIN SELECT RAISE(ABORT,'Reconciliation evidence is immutable'); END;
CREATE TRIGGER tt_reconcile_signoffs_update BEFORE UPDATE ON tt_reconcile_signoffs BEGIN SELECT RAISE(ABORT,'Reconciliation evidence is immutable'); END;
CREATE TRIGGER tt_reconcile_signoffs_delete BEFORE DELETE ON tt_reconcile_signoffs BEGIN SELECT RAISE(ABORT,'Reconciliation evidence is immutable'); END;
CREATE TRIGGER tt_journal_reconcile_clock AFTER INSERT ON tt_journal BEGIN UPDATE tt_reconcile_clock SET version=version+1 WHERE id=1; END;
CREATE TRIGGER tt_trust_allocations_reconcile_clock AFTER INSERT ON tt_trust_allocations BEGIN UPDATE tt_reconcile_clock SET version=version+1 WHERE id=1; END;
CREATE TRIGGER tt_trust_mappings_reconcile_clock AFTER INSERT ON tt_trust_mappings BEGIN UPDATE tt_reconcile_clock SET version=version+1 WHERE id=1; END;
CREATE TRIGGER tt_trust_recordings_reconcile_clock AFTER INSERT ON tt_trust_recordings BEGIN UPDATE tt_reconcile_clock SET version=version+1 WHERE id=1; END;
CREATE TRIGGER tt_reconcile_statements_reconcile_clock AFTER INSERT ON tt_reconcile_statements BEGIN UPDATE tt_reconcile_clock SET version=version+1 WHERE id=1; END;
CREATE TRIGGER tt_reconcile_matches_reconcile_clock AFTER INSERT ON tt_reconcile_matches BEGIN UPDATE tt_reconcile_clock SET version=version+1 WHERE id=1; END;
CREATE TRIGGER tt_reconcile_sources_reconcile_clock AFTER INSERT ON tt_reconcile_sources BEGIN UPDATE tt_reconcile_clock SET version=version+1 WHERE id=1; END;
CREATE TRIGGER tt_reconcile_outstanding_reconcile_clock AFTER INSERT ON tt_reconcile_outstanding BEGIN UPDATE tt_reconcile_clock SET version=version+1 WHERE id=1; END;
